$ErrorActionPreference='Stop';$here=$PSScriptRoot;$repo=Split-Path $here -Parent;$root=Join-Path ([IO.Path]::GetTempPath()) ('maya-isolation-repair-'+[guid]::NewGuid().ToString('N'))
Import-Module (Join-Path $here 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue;Import-Module (Join-Path $here 'Repato.Deployment.v4.psm1') -Force -WarningAction SilentlyContinue;Import-Module (Join-Path $here 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue;Import-Module (Join-Path $here 'Repato.MayaQaRunnerRepair.psm1') -Force -WarningAction SilentlyContinue
function Reject($n,[scriptblock]$x){$r=$false;try{&$x|Out-Null}catch{$r=$true};if(!$r){throw "Unsafe isolation repair accepted: $n"}}
try{New-Item -ItemType Directory $root|Out-Null;$run='qa-run-'+[guid]::NewGuid().ToString('N');$b=New-MayaQaBootstrap -StoreRoot $root -QaWorkflowId 'create-plan-views-v1' -RunId $run;$handoff='handoff-'+[guid]::NewGuid().ToString('N');$attempt='attempt-'+[guid]::NewGuid().ToString('N')
 $policy=Join-Path $repo 'QA\MachineWideAddins.allowlist.json';$hash=(Get-FileHash $policy -Algorithm SHA256).Hash;$null=Invoke-RepatoStoreMutation $root {param($d,$p)$t=Find-RepatoTask $d $b.TaskId;$w=@($t.deploymentWorkflows|Where-Object workflowId -ceq $b.WorkflowId)[0];$isolation=[pscustomobject]@{Allowed=$true};$w|Add-Member NoteProperty qaBuildEvidence ([pscustomobject]@{Isolation=$isolation}) -Force;$w|Add-Member NoteProperty qaHandoffId $handoff -Force;$w|Add-Member NoteProperty qaHandoff ([pscustomobject]@{HandoffId=$handoff;TaskId=$b.TaskId;HandoffStatus='ready';CoordinatorRunId=$run;Isolation=[pscustomobject]@{Allowed=$true}}) -Force;$t|Add-Member NoteProperty mayaTaraAttempt ([pscustomobject]@{WorkflowId=$b.WorkflowId;AttemptId=$attempt;RunId=$run;Stage='prepared'}) -Force;$t|Add-Member NoteProperty mayaTaraQaPacket ([pscustomobject]@{TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;HandoffId=$handoff;AttemptId=$attempt;RunId=$run;Stage='prepared'}) -Force;$t};$args=@{StoreRoot=$root;TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;HandoffId=$handoff;AttemptId=$attempt;ExpectedRunId=$run;PolicyPath=$policy;ExpectedPolicySha256=$hash;RevitProcessProvider={@()}}
 Reject 'wrong policy hash' {Repair-MayaQaPreparedIsolationPolicyEvidence @args -ExpectedPolicySha256 ('F'*64)};Reject 'wrong run' {Repair-MayaQaPreparedIsolationPolicyEvidence @args -ExpectedRunId 'qa-run-00000000000000000000000000000000'};Reject 'live Revit' {Repair-MayaQaPreparedIsolationPolicyEvidence @args -RevitProcessProvider {[pscustomobject]@{Id=1}}}
 $b=Find-RepatoTask (Read-RepatoTaskStore $root) $args.TaskId;$bw=@($b.deploymentWorkflows|? workflowId -ceq $args.WorkflowId)[0];$build=$bw.qaBuildEvidence|ConvertTo-Json -Depth 20;$handoff=$bw.qaHandoff|ConvertTo-Json -Depth 20;$packet=$b.mayaTaraQaPacket|ConvertTo-Json -Depth 20;$attempt=$b.mayaTaraAttempt|ConvertTo-Json -Depth 20
 $done=Repair-MayaQaPreparedIsolationPolicyEvidence @args;$a=Find-RepatoTask (Read-RepatoTaskStore $root) $args.TaskId;$aw=@($a.deploymentWorkflows|? workflowId -ceq $args.WorkflowId)[0];$aw.qaBuildEvidence.Isolation=$bw.qaBuildEvidence.Isolation;$aw.qaHandoff.Isolation=$bw.qaHandoff.Isolation
 if(($aw.qaBuildEvidence|ConvertTo-Json -Depth 20) -cne $build -or ($aw.qaHandoff|ConvertTo-Json -Depth 20) -cne $handoff -or ($a.mayaTaraQaPacket|ConvertTo-Json -Depth 20) -cne $packet -or ($a.mayaTaraAttempt|ConvertTo-Json -Depth 20) -cne $attempt -or $a.mayaTaraExecution){throw 'Isolation repair changed unrelated prepared state.'};$aw.qaBuildEvidence.Isolation=[pscustomobject]@{PolicyPath=$done.PolicyPath;PolicySha256=$done.PolicySha256;Allowed=$true};$aw.qaHandoff.Isolation=$aw.qaBuildEvidence.Isolation
 if($done.PolicySha256 -ine $hash){throw 'Canonical isolation evidence was not repaired.'};Reject 'duplicate/non-incomplete shape' {Repair-MayaQaPreparedIsolationPolicyEvidence @args};'Prepared isolation policy repair passed: canonical path/hash, two-field repair, preservation and guarded rejection'
}finally{if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force}}
